400	import java.math.BigDecimal;
401	import java.time.LocalDate;
402	import java.time.format.DateTimeParseException;
403	import java.util.ArrayList;
404	import java.util.List;
405	import java.util.regex.Pattern;
406	import net.officefloor.hq.app.role.Role;
407	import net.officefloor.hq.app.role.RoleStore;
408	import net.officefloor.hq.app.sheet.InvalidSheetException;
409	import net.officefloor.plugin.variable.Out;
410	import org.springframework.web.bind.annotation.PathVariable;
411	import org.springframework.web.bind.annotation.RequestBody;
412	
413	public class ValidateSetting {
414	    /** 0.00 or more, with up to two decimals. */
415	    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
416	    /** A whole number of days, 0 or more. */
417	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
418	
419	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingRequest request, Out<SettingInput> body, RoleStore roles) throws InvalidSheetException {
420	        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
421	        String key = request == null || request.key() == null ? "" : request.key().trim();
422	        boolean floor = SettingStore.FLOOR.equals(key);
423	        boolean terms = SettingStore.TERMS.equals(key);
424	        boolean gradeTerms = key.startsWith(SettingStore.TERMS_PREFIX)
425	                && SettingStore.GRADES.contains(key.substring(SettingStore.TERMS_PREFIX.length()));
426	        boolean late = SettingStore.LATE_PCT.equals(key);
427	        boolean numbering = SettingStore.PERIOD_NUMBERING_FROM.equals(key);
428	        boolean dated = SettingStore.POLICY_DATE.equals(key) || numbering;
429	        boolean cap = SettingStore.CAP.equals(key);
430	        boolean proof = SettingStore.PROOF_THRESHOLD.equals(key);
431	        boolean note = SettingStore.NOTE_THRESHOLD.equals(key);
432	        if (SettingStore.GRACE_DAYS.equals(key)) {
433	            String value = request.value() == null ? "" : request.value().trim();
434	            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
435	                throw new InvalidSheetException("The grace days must be a whole number of days, 0 or more, or blank");
436	            }
437	            body.set(new SettingInput(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null,
438	                    request.user()));
439	            return;
440	        }
441	        if (key.startsWith(SettingStore.PERM_PREFIX)
442	                && SettingStore.PERM_ACTIONS.contains(key.substring(SettingStore.PERM_PREFIX.length()))) {
443	            body.set(new SettingInput(key, perm(request.value()), null, request.user()));
444	            return;
445	        }
446	        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !proof && !note && !floor && !terms && !gradeTerms && !late && !dated) {
447	            throw new InvalidSheetException("Not a setting: " + key);
448	        }
449	        String value = request.value() == null ? "" : request.value().trim();
450	        String fromValue = request.from() == null ? "" : request.from().trim();
451	        LocalDate from = null;
452	        if (!dated && !fromValue.isEmpty()) {
453	            try {
454	                from = LocalDate.parse(fromValue);
455	            } catch (DateTimeParseException e) {
456	                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
457	            }
458	        }
459	        if (dated) {
460	            if (value.isEmpty()) {
461	                body.set(new SettingInput(key, null, from, request.user()));
462	                return;
463	            }
464	            try {
465	                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
466	            } catch (DateTimeParseException e) {
467	                throw new InvalidSheetException((numbering ? "The period numbering from" : "The policy date")
468	                        + " must be a date (YYYY-MM-DD), or blank");
469	            }
470	            return;
471	        }
472	        if (gradeTerms) {
473	            if (value.isEmpty()) {
474	                body.set(new SettingInput(key, null, from, request.user()));
475	                return;
476	            }
477	            if (!DAYS.matcher(value).matches()) {
478	                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
479	            }
480	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
481	            return;
482	        }
483	        if (terms) {
484	            if (value.isEmpty()) {
485	                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), from, request.user()));
486	                return;
487	            }
488	            if (!DAYS.matcher(value).matches()) {
489	                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
490	            }
491	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
492	            return;
493	        }
494	        if (value.isEmpty() && floor) {
495	            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), from, request.user()));
496	            return;
497	        }
498	        if (value.isEmpty() && late) {
499	            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
500	            return;
501	        }
502	        if (value.isEmpty()) {
503	            body.set(new SettingInput(key, null, from, request.user()));
504	            return;
505	        }
506	        if (!LIMIT.matcher(value).matches()) {
507	            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
508	                    : late ? "The late percent must be 0.00 or more with up to two decimals"
509	                    : proof ? "The proof threshold must be 0.00 or more with up to two decimals, or blank"
510	                    : note ? "The note threshold must be 0.00 or more with up to two decimals, or blank"
511	                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
512	                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
513	        }
514	        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
515	    }
516	
517	    /** The roles listed, comma separated without spaces, or null when blank (the standing rule). */
518	    private static String perm(String raw) throws InvalidSheetException {
519	        String value = raw == null ? "" : raw.trim();
520	        if (value.isEmpty()) {
521	            return null;
522	        }
523	        List<String> roles = new ArrayList<>();
524	        for (String part : value.split(",")) {
525	            String role = part.trim();
526	            if (Role.of(role) == null || Role.of(role) == Role.VIEWER) {
527	                throw new InvalidSheetException("A permission lists roles (clerk, steward), comma separated, or is blank");
528	            }
529	            if (!roles.contains(role)) {
530	                roles.add(role);
531	            }
532	        }
533	        return String.join(",", roles);
534	    }
535	}
