578	import { useState } from 'react';
579	import { useMutation, useQueryClient } from '@tanstack/react-query';
580	import { HttpError, postJson } from '../../api/http';
581	import { useSubmitOnce } from '../../query/useSubmitOnce';
582	import { HomeMain } from '../../slots/defs/homeMain';
583	import { useCurrentSheet, useCurrentUser } from '../../session/session';
584	import { type Settings, settingsKey, useSettings } from './settings';
585	
586	const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
587	
588	/** The standing rule each action keeps while its permission is blank. */
589	const STANDING_PERMS: Record<(typeof PERM_ACTIONS)[number], string> = {
590	  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', reassign: 'steward', close: 'clerk,steward', reopen: 'steward',
591	};
592	
593	type PermKey = `perm-${(typeof PERM_ACTIONS)[number]}`;
594	
595	type Key = 'clerk-limit' | 'floor' | 'terms' | 'terms-A' | 'terms-B' | 'terms-C' | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'cap' | 'proof-threshold' | 'note-threshold' | 'grace-days' | PermKey;
596	
597	const GRADES = ['A', 'B', 'C'] as const;
598	
599	/** The settings that carry a figure: each is saved from a from-date (blank for the sheet's today). */
600	type DatedKey = Exclude<Key, 'policy-date' | 'period-numbering-from' | 'grace-days' | PermKey>;
601	
602	const NO_FROM: Record<DatedKey, string> = { 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'late-pct': '', cap: '', 'proof-threshold': '', 'note-threshold': '' };
603	
604	const isDated = (k: Key): k is DatedKey => k in NO_FROM;
605	
606	// The sheet's settings in force, and the form that changes them: the clerk limit (blank for none),
607	// the floor (blank for its default), the terms in days (blank for 14), each grade's own terms (blank
608	// for the sheet's terms) and the late percent (blank for
609	// 0.00), the policy date rounding turns on (blank for the sheet's today) and the date claims opened
610	// are numbered per period from (blank for off), and the cap on a person's due-total (blank for none), and the proof threshold above which a claim's due needs a proof to be settled or approved (blank for none), and the note threshold above which a claim's due needs a note to be opened (blank for none). Saving changes the setting last touched, so a field left blank does not clear the others.
611	// Each setting that carries a figure is saved from its from-date (blank for the sheet's today), and shows
612	// the value in force on the sheet's today; the policy date and period numbering date are not dated.
613	// The permission matrix gives, for each action, the roles that may take it, comma separated (blank keeps
614	// the standing rule, shown as the placeholder); it is not dated. The grace days (blank for off, not
615	// dated) are the whole days after its to-date an open period is closed when the sheet's today moves.
616	function SheetSettings() {
617	  const [user] = useCurrentUser();
618	  const [sheet] = useCurrentSheet();
619	  const settings = useSettings(sheet);
620	  const [values, setValues] = useState<Record<Key, string>>({ 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', cap: '', 'proof-threshold': '', 'note-threshold': '', 'grace-days': '',
621	    'perm-open': '', 'perm-settle': '', 'perm-void': '', 'perm-reassign': '', 'perm-close': '', 'perm-reopen': '' });
622	  const [froms, setFroms] = useState<Record<DatedKey, string>>(NO_FROM);
623	  const [key, setKey] = useState<Key>('clerk-limit');
624	  const queryClient = useQueryClient();
625	
626	  const save = useMutation({
627	    mutationFn: ({ key, value, from }: { key: Key; value: string; from: string }) =>
628	      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { key, value, from, user }),
629	    onSuccess: async (_, { key }) => {
630	      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
631	      setValues((v) => ({ ...v, [key]: '' }));
632	      if (isDated(key)) setFroms((f) => ({ ...f, [key]: '' }));
633	    },
634	  });
635	  const submit = useSubmitOnce(save);
636	
637	  const field = (k: Key, placeholder: string, inputMode: 'decimal' | 'text' = 'decimal') => (
638	    <input
639	      data-testid={`setting-${k}`}
640	      placeholder={placeholder}
641	      inputMode={inputMode}
642	      value={values[k]}
643	      onFocus={() => setKey(k)}
644	      onChange={(e) => {
645	        setValues({ ...values, [k]: e.target.value });
646	        setKey(k);
647	        save.reset();
648	      }}
649	    />
650	  );
651	
652	  const from = (k: DatedKey) => (
653	    <input
654	      data-testid={`setting-${k}-from`}
655	      placeholder="From YYYY-MM-DD (blank for today)"
656	      value={froms[k]}
657	      onFocus={() => setKey(k)}
658	      onChange={(e) => {
659	        setFroms({ ...froms, [k]: e.target.value });
660	        setKey(k);
661	        save.reset();
662	      }}
663	    />
664	  );
665	
666	  return (
667	    <section data-testid="settings">
668	      <h2>Settings</h2>
669	      <form
670	        data-testid="settings-form"
671	        onSubmit={(e) => {
672	          e.preventDefault();
673	          submit({ key, value: values[key], from: isDated(key) ? froms[key] : '' });
674	        }}
675	      >
676	        Clerk limit <strong data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</strong>{' '}
677	        {field('clerk-limit', 'Clerk limit (blank for none)')}{' '}{from('clerk-limit')}{' '}
678	        Floor <strong data-testid="setting-floor-current">{settings.data?.floor ?? ''}</strong>{' '}
679	        {field('floor', 'Floor (blank for 1.00)')}{' '}{from('floor')}{' '}
680	        Terms <strong data-testid="setting-terms-current">{settings.data?.terms ?? ''}</strong>{' '}
681	        {field('terms', 'Terms in days (blank for 14)')}{' '}{from('terms')}{' '}
682	        {GRADES.map((g) => (
683	          <span key={g}>
684	            Terms {g} <strong data-testid={`setting-terms-${g}-current`}>{settings.data?.gradeTerms?.[g] ?? ''}</strong>{' '}
685	            {field(`terms-${g}`, `Terms for grade ${g} (blank for the sheet's)`)}{' '}{from(`terms-${g}`)}{' '}
686	          </span>
687	        ))}
688	        Late percent <strong data-testid="setting-late-pct-current">{settings.data?.latePct ?? ''}</strong>{' '}
689	        {field('late-pct', 'Late percent (blank for 0.00)')}{' '}{from('late-pct')}{' '}
690	        Policy date <strong data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</strong>{' '}
691	        {field('policy-date', 'Policy date YYYY-MM-DD (blank for today)', 'text')}{' '}
692	        Period numbering from <strong data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</strong>{' '}
693	        {field('period-numbering-from', 'Period numbering from YYYY-MM-DD (blank for off)', 'text')}{' '}
694	        Cap <strong data-testid="setting-cap-current">{settings.data?.cap ?? ''}</strong>{' '}
695	        {field('cap', 'Cap (blank for none)')}{' '}{from('cap')}{' '}
696	        Proof threshold <strong data-testid="setting-proof-threshold-current">{settings.data?.proofThreshold ?? ''}</strong>{' '}
697	        {field('proof-threshold', 'Proof threshold (blank for none)')}{' '}{from('proof-threshold')}{' '}
698	        Note threshold <strong data-testid="setting-note-threshold-current">{settings.data?.noteThreshold ?? ''}</strong>{' '}
699	        {field('note-threshold', 'Note threshold (blank for none)')}{' '}{from('note-threshold')}{' '}
700	        Grace days <strong data-testid="setting-grace-days-current">{settings.data?.graceDays ?? ''}</strong>{' '}
701	        {field('grace-days', 'Grace days (blank for off)')}{' '}
702	        {PERM_ACTIONS.map((a) => (
703	          <span key={a}>
704	            May {a} <strong data-testid={`setting-perm-${a}-current`}>{settings.data?.perms?.[a] ?? ''}</strong>{' '}
705	            {field(`perm-${a}`, `Roles that may ${a}, comma separated (blank for ${STANDING_PERMS[a]})`, 'text')}{' '}
706	          </span>
707	        ))}
708	        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
709	          Save settings
710	        </button>
711	        {save.isError && (
712	          <span data-testid="settings-error" role="alert">
713	            {' '}
714	            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The settings were refused.'}
715	          </span>
716	        )}
717	      </form>
718	    </section>
719	  );
720	}
721	
722	export const contribution = HomeMain.fill({ order: 48, Component: SheetSettings });
723	import { useQuery } from '@tanstack/react-query';
724	import { getJson } from '../../api/http';
725	import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
726	import { useAsOf } from '../../session/session';
727	
728	/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
729	 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
730	 *  whole days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
731	 *  claim's figure charged at each full 30 days it is overdue (the one in force on that boundary); `policyDate` (yyyy-MM-dd) is the date
732	 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
733	 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
734	 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
735	 *  due-total may be, null for no cap; `proofThreshold` (two decimals) is the due above which a claim needs a proof
736	 *  before it is settled or approved, null for none; `noteThreshold` (two decimals) is the due above which a
737	 *  claim needs a note before it is opened, null for none. Each of these that carries a figure is the one in force on the sheet's today.
738	 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
739	 *  a claim's floor and late percent are those in force on its date. `perms` is the permission matrix: the roles
740	 *  that may take each action (open, settle, void, reassign, close, reopen), comma separated, by action; null when
741	 *  blank (the standing rule). `graceDays` is the whole days after its to-date an open period is closed when the
742	 *  sheet's today moves, null when blank (off). */
743	export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
744	  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; proofThreshold: string | null;
745	  floorFrom: Dated[]; latePctFrom: Dated[]; perms: Record<string, string | null>;
746	  graceDays: string | null; noteThreshold: string | null };
747	
748	/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
749	export type Dated = { from: string; value: string | null };
750	
751	/** The floor a sheet has before any is recorded. */
752	const STARTING_FLOOR = '1.00';
753	
754	/** The late percent a sheet has before any is recorded. */
755	const STARTING_LATE_PCT = '0.00';
756	
757	/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
758	export function valueOn(history: Dated[], date: string, starting: string): string {
759	  let found: string | null = null;
760	  for (const d of history) if (d.from <= date) found = d.value;
761	  return found ?? starting;
762	}
763	
764	/** The floor in force on each date; undefined until the settings are read. */
765	export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
766	  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
767	}
768	
769	/** The late percent in force on each date; undefined until the settings are read. */
770	export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
771	  return settings && ((date) => valueOn(settings.latePctFrom, date, STARTING_LATE_PCT));
772	}
773	
774	/** Under the sheet's key, so loading the sheet again re-reads its settings. */
775	export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;
776	
777	export function useSettings(sheet: string) {
778	  const [asOf] = useAsOf();
779	  return useQuery({
780	    queryKey: asOfKey(settingsKey(sheet), asOf),
781	    queryFn: () => getJson<Settings>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/settings`, asOf)),
782	    enabled: sheet !== '',
783	  });
784	}
785	-- The roles the sheet assigns: a user name with no row here is a clerk.
786	CREATE TABLE sheet_role (
787	    sheet_id  VARCHAR(255) NOT NULL,
788	    user_name VARCHAR(255) NOT NULL,
789	    role      VARCHAR(32)  NOT NULL,
790	    PRIMARY KEY (sheet_id, user_name)
791	);
792	-- The sheet's settings, by key; a null value is blank (for clerk-limit: no limit). A key with no
793	-- row here has never been set.
794	CREATE TABLE sheet_setting (
795	    sheet_id    VARCHAR(255) NOT NULL,
796	    setting_key VARCHAR(64)  NOT NULL,
797	    setting_value VARCHAR(255),
798	    PRIMARY KEY (sheet_id, setting_key)
799	);
800	-- The settings that carry a figure are dated: each value is recorded from a from-date, and the value in
801	-- force on a date is the one with the latest from-date on or before it (before every from-date, the
802	-- sheet's starting value). A null value is blank (for clerk-limit and cap: none; for a grade's terms:
803	-- the sheet's). The policy date and the period numbering date stay undated in sheet_setting.
804	CREATE TABLE sheet_setting_from (
805	    sheet_id      VARCHAR(255) NOT NULL,
806	    setting_key   VARCHAR(64)  NOT NULL,
807	    from_date     DATE         NOT NULL,
808	    setting_value VARCHAR(255),
809	    PRIMARY KEY (sheet_id, setting_key, from_date)
810	);
811	-- A value set before settings were dated holds from the start.
812	INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
813	    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
814	    WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
815	DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
