package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Records a stored setting: SETTING_CHANGED sheet=<id> by=<user> key=<key> value=<value> (an empty
 *  value when blank), then from=<date> when a from-date was given, then how the change moved the sheet's figures (the floor moves live dues). */
public class AuditSettingChanged {
    public void audit(@PathVariable("sheetId") String sheetId, @Val SettingInput setting, @Val Rollup before,
            Audit audit, RollupService rollups) {
        audit.record("SETTING_CHANGED sheet=" + sheetId.trim() + " by=" + setting.user() + " key=" + setting.key()
                + " value=" + (setting.value() == null ? "" : setting.value())
                + (setting.from() == null ? "" : " from=" + setting.from()));
        rollups.record(sheetId.trim(), setting.user(), before);
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The settings in force on the sheet's today, and the floor and late percent recorded by from-date; as of a
 *  date, as they stood at the end of it, in force on that date. */
public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, SettingStore settings, SheetStore sheets,
            ObjectResponse<SettingsResponse> response) {
        String sheet = sheetId.trim();
        LocalDate on = History.date(asOf);
        SettingStore store = on == null ? settings : settings.asOf(on);
        LocalDate today = on == null ? sheets.today(sheet) : on;
        response.send(new SettingsResponse(store.find(sheet, SettingStore.CLERK_LIMIT),
                store.floors(sheet).apply(today).setScale(2).toPlainString(),
                String.valueOf(store.terms(sheet, today)),
                store.latePcts(sheet).apply(today).setScale(2).toPlainString(),
                store.find(sheet, SettingStore.POLICY_DATE),
                store.find(sheet, SettingStore.PERIOD_NUMBERING_FROM), gradeTerms(sheet, today, store),
                store.find(sheet, SettingStore.CAP), store.find(sheet, SettingStore.PROOF_THRESHOLD),
                history(sheet, SettingStore.FLOOR, store), history(sheet, SettingStore.LATE_PCT, store),
                store.perms(sheet), store.find(sheet, SettingStore.GRACE_DAYS),
                store.find(sheet, SettingStore.NOTE_THRESHOLD)));
    }

    private static Map<String, String> gradeTerms(String sheetId, LocalDate today, SettingStore store) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : SettingStore.GRADES) {
            terms.put(grade, String.valueOf(store.terms(sheetId, grade, today)));
        }
        return terms;
    }

    private static List<SettingsResponse.Dated> history(String sheetId, String key, SettingStore store) {
        List<SettingsResponse.Dated> values = new ArrayList<>();
        store.history(sheetId, key).forEach((from, value) -> values.add(new SettingsResponse.Dated(from.toString(), value)));
        return values;
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Records the setting; a dated one from its from-date, else from the sheet's today. */
public class SaveSetting {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingInput setting, SettingStore store,
            SheetStore sheets) {
        String sheet = sheetId.trim();
        store.set(sheet, setting.key(), setting.value(),
                setting.from() != null ? setting.from() : sheets.today(sheet));
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;

/** A validated setting change: the key, its value as stored (null when blank), the from-date given for a
 *  dated setting (null when blank: then the sheet's today) and who changes it. */
public record SettingInput(String key, String value, LocalDate from, String user) {
}
package net.officefloor.hq.app.setting;

/** Body of POST /api/sheets/{sheetId}/settings: the setting's key, its new value (blank to clear it),
 *  the date it holds from (blank for the sheet's today; a setting that is not dated ignores it) and who
 *  changes it. */
public record SettingRequest(String key, String value, String from, String user) {
}
package net.officefloor.hq.app.setting;

import java.util.List;
import java.util.Map;

/** The sheet's settings as the front end reads them: {@code clerkLimit} has two decimals, null for
 *  no limit; {@code floor} has two decimals; {@code terms} is the whole days after its date a claim is
 *  due by;
 *  {@code latePct} has two decimals; {@code policyDate} is the date rounding turns on, null when blank
 *  (then the sheet's today); {@code periodNumberingFrom} is the date from which claims opened are
 *  numbered per period, null when blank (off); {@code gradeTerms} is the terms in force for each grade
 *  (its own, else the sheet's), by grade; {@code cap} has two decimals, the most a person's due-total may
 *  be, null for no cap; {@code proofThreshold} has two decimals, the due above which a claim needs a proof
 *  before it is settled or approved, null for none; {@code noteThreshold} has two decimals, the due above
 *  which a claim needs a note before it is opened, null for none. Each of these that carries a figure is the one in force on the sheet's today.
 *  {@code floorFrom} and {@code latePctFrom} are the floor and late percent recorded, oldest from-date
 *  first (a claim's floor is the one in force on its date, its late percent the one in force on each 30-day boundary). {@code perms} is the permission
 *  matrix: the roles that may take each action (open, settle, void, reassign, close, reopen), comma
 *  separated, by action; null when blank (the standing rule).
 *  {@code graceDays} is the whole days after its to-date an open period is closed by a new today, null when blank (off). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, Map<String, String> gradeTerms, String cap, String proofThreshold, List<Dated> floorFrom,
        List<Dated> latePctFrom, Map<String, String> perms, String graceDays,
        String noteThreshold) {

    /** A value recorded from a date (yyyy-MM-dd). */
    public record Dated(String from, String value) {
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import java.util.function.Function;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The settings kept per sheet, by key. A setting never set, or set blank, has no value. The settings
 *  that carry a figure (the clerk limit, the floor, the cap, the proof threshold, the note threshold, the terms, a grade's terms and the late
 *  percent) are dated: each value is recorded from a from-date, and the value in force on a date is the
 *  one with the latest from-date on or before it (none before every from-date, then the sheet's starting
 *  value). The policy date, the period numbering date, the grace days and the permission matrix are not dated. */
@Repository
public class SettingStore {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String CAP = "cap";

    /** Above it a claim's due needs a proof before it is settled or approved. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** Above it a claim's due needs a note before it is opened. */
    public static final String NOTE_THRESHOLD = "note-threshold";

    public static final String TERMS = "terms";

    /** The key of a grade's own terms: terms-A, terms-B or terms-C. */
    public static final String TERMS_PREFIX = "terms-";

    /** The grades that may have terms of their own. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    public static final String LATE_PCT = "late-pct";

    public static final String POLICY_DATE = "policy-date";

    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The whole days after its to-date an open period is closed by a new today; blank for off. */
    public static final String GRACE_DAYS = "grace-days";

    /** The key of an action's permission: perm-open, perm-settle, and so on. */
    public static final String PERM_PREFIX = "perm-";

    /** The roles that may take each action while its permission is blank (the standing rule). */
    public static final Map<String, List<Role>> STANDING_PERMS = Map.of(
            "open", List.of(Role.CLERK, Role.STEWARD), "settle", List.of(Role.CLERK, Role.STEWARD),
            "void", List.of(Role.CLERK, Role.STEWARD), "close", List.of(Role.CLERK, Role.STEWARD),
            "reassign", List.of(Role.STEWARD), "reopen", List.of(Role.STEWARD));

    /** The actions of the permission matrix, in the order the screen shows them. */
    public static final List<String> PERM_ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    /** The late percent a sheet has until one is set. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The terms (days) a sheet has until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** The floor a sheet has until one is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    private final JdbcTemplate jdbc;

    private final SheetStore sheets;

    /** Where the undated and the dated settings are read from: their tables, or as they stood at the end of
     *  {@link #asOf}. */
    private final String undated;

    private final String dated;

    /** The date that stands in for the sheet's today; null to read the sheet's today. */
    private final LocalDate asOf;

    @Autowired
    public SettingStore(JdbcTemplate jdbc, SheetStore sheets) {
        this(jdbc, sheets, "sheet_setting", "sheet_setting_from", null);
    }

    private SettingStore(JdbcTemplate jdbc, SheetStore sheets, String undated, String dated, LocalDate asOf) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.undated = undated;
        this.dated = dated;
        this.asOf = asOf;
    }

    /** The settings as they stood at the end of the date (see {@link History}), with the date standing in for
     *  the sheet's today, to read only. */
    public SettingStore asOf(LocalDate date) {
        return new SettingStore(jdbc, sheets, History.asOf("sheet_setting", "sheet_id, setting_key", date),
                History.asOf("sheet_setting_from", "sheet_id, setting_key, from_date", date), date);
    }

    private LocalDate today(String sheetId) {
        return asOf != null ? asOf : sheets.today(sheetId);
    }

    /** Whether the key's values are recorded from a from-date. */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !GRACE_DAYS.equals(key)
                && !key.startsWith(PERM_PREFIX);
    }

    /** Whether the role may take the action (one of {@link #PERM_ACTIONS}): the roles listed in its
     *  permission, else, when blank, the standing rule. */
    public boolean allows(String sheetId, String action, Role role) {
        if (role == Role.VIEWER) {
            return false;
        }
        String value = find(sheetId, PERM_PREFIX + action);
        if (value == null) {
            return STANDING_PERMS.get(action).contains(role);
        }
        return Arrays.stream(value.split(",")).map(String::trim).anyMatch(r -> r.equals(role.shown()));
    }

    /** The permissions recorded, by action; a blank one is null (the standing rule). */
    public Map<String, String> perms(String sheetId) {
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : PERM_ACTIONS) {
            perms.put(action, find(sheetId, PERM_PREFIX + action));
        }
        return perms;
    }

    /** The setting's value (a dated one's in force on the sheet's today), or null when it has none. */
    public String find(String sheetId, String key) {
        if (isDated(key)) {
            return findOn(sheetId, key, today(sheetId));
        }
        List<String> found = jdbc.queryForList(
                "SELECT setting_value FROM " + undated + " WHERE sheet_id = ? AND setting_key = ?", String.class,
                sheetId, key);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The dated setting's values recorded, by from-date (a null value is blank). */
    public NavigableMap<LocalDate, String> history(String sheetId, String key) {
        NavigableMap<LocalDate, String> values = new TreeMap<>();
        jdbc.query("SELECT from_date, setting_value FROM " + dated + " WHERE sheet_id = ? AND setting_key = ?",
                rs -> {
                    values.put(rs.getObject("from_date", LocalDate.class), rs.getString("setting_value"));
                }, sheetId, key);
        return values;
    }

    /** The dated setting's value in force on the date, or null when it has none then. */
    public String findOn(String sheetId, String key, LocalDate date) {
        return on(history(sheetId, key), date);
    }

    private static String on(NavigableMap<LocalDate, String> history, LocalDate date) {
        var entry = date == null ? null : history.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    /** The most a clerk may settle a claim's due at (the one in force on the sheet's today), or null for no limit. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = find(sheetId, CLERK_LIMIT);
        return value == null ? null : new BigDecimal(value);
    }

    /** The most a person's due-total may be (the one in force on the sheet's today), or null for no cap. */
    public BigDecimal cap(String sheetId) {
        String value = find(sheetId, CAP);
        return value == null ? null : new BigDecimal(value);
    }

    /** The due above which a claim dated on the date needs a proof before it is settled or approved (the
     *  one in force on that date), or null for none. */
    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
        String value = findOn(sheetId, PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The due above which a claim dated on the date needs a note before it is opened (the one in force on
     *  that date), or null for none. */
    public BigDecimal noteThreshold(String sheetId, LocalDate date) {
        String value = findOn(sheetId, NOTE_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The least a claim's live due may be, in force on each date: the floor recorded then, else 1.00. Read once, for many claims. */
    public Function<LocalDate, BigDecimal> floors(String sheetId) {
        return amounts(history(sheetId, FLOOR), DEFAULT_FLOOR);
    }

    /** The percent of an overdue claim's figure charged at each 30-day boundary it is overdue past, in force on each
     *  date: the one recorded then, else 0.00. Read once, for many claims. */
    public Function<LocalDate, BigDecimal> latePcts(String sheetId) {
        return amounts(history(sheetId, LATE_PCT), DEFAULT_LATE_PCT);
    }

    private static Function<LocalDate, BigDecimal> amounts(NavigableMap<LocalDate, String> history,
            BigDecimal starting) {
        return date -> {
            String value = on(history, date);
            return value == null ? starting : new BigDecimal(value);
        };
    }

    /** The due-total at most the cap (none when null). */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return cap != null && dueTotal.compareTo(cap) > 0 ? cap.setScale(2) : dueTotal;
    }

    /** The days after its date a claim is due by, in force on the date: the terms recorded then, else 14. */
    public int terms(String sheetId, LocalDate date) {
        String value = findOn(sheetId, TERMS, date);
        return value == null ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms (days) in force on the date, or null when it has none then (then the sheet's terms). */
    public Integer gradeTerms(String sheetId, String grade, LocalDate date) {
        String value = findOn(sheetId, TERMS_PREFIX + grade, date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The days after its date a claim of a person of the grade is due by, in force on the date: the
     *  grade's own terms, else the sheet's. */
    public int terms(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTerms(sheetId, grade, date);
        return own == null ? terms(sheetId, date) : own;
    }

    /** The date the sheet's rounding turns on, or null when blank (then the sheet's today). */
    public LocalDate policyDate(String sheetId) {
        String value = find(sheetId, POLICY_DATE);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The date from which claims opened are numbered per period, or null when blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The whole days after its to-date an open period is closed by a new today, or null when blank (off). */
    public Integer graceDays(String sheetId) {
        String value = find(sheetId, GRACE_DAYS);
        return value == null ? null : Integer.valueOf(value);
    }

    /** Records the setting's value; a dated one's from the date (replacing a value recorded from it). */
    public void set(String sheetId, String key, String value, LocalDate from) {
        if (isDated(key)) {
            jdbc.update("MERGE INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value) "
                    + "KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)", sheetId, key, from, value);
            return;
        }
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key) "
                + "VALUES (?, ?, ?)", sheetId, key, value);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0.00 or more, with up to two decimals. */
    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingRequest request, Out<SettingInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        boolean floor = SettingStore.FLOOR.equals(key);
        boolean terms = SettingStore.TERMS.equals(key);
        boolean gradeTerms = key.startsWith(SettingStore.TERMS_PREFIX)
                && SettingStore.GRADES.contains(key.substring(SettingStore.TERMS_PREFIX.length()));
        boolean late = SettingStore.LATE_PCT.equals(key);
        boolean numbering = SettingStore.PERIOD_NUMBERING_FROM.equals(key);
        boolean dated = SettingStore.POLICY_DATE.equals(key) || numbering;
        boolean cap = SettingStore.CAP.equals(key);
        boolean proof = SettingStore.PROOF_THRESHOLD.equals(key);
        boolean note = SettingStore.NOTE_THRESHOLD.equals(key);
        if (SettingStore.GRACE_DAYS.equals(key)) {
            String value = request.value() == null ? "" : request.value().trim();
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The grace days must be a whole number of days, 0 or more, or blank");
            }
            body.set(new SettingInput(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null,
                    request.user()));
            return;
        }
        if (key.startsWith(SettingStore.PERM_PREFIX)
                && SettingStore.PERM_ACTIONS.contains(key.substring(SettingStore.PERM_PREFIX.length()))) {
            body.set(new SettingInput(key, perm(request.value()), null, request.user()));
            return;
        }
        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !proof && !note && !floor && !terms && !gradeTerms && !late && !dated) {
            throw new InvalidSheetException("Not a setting: " + key);
        }
        String value = request.value() == null ? "" : request.value().trim();
        String fromValue = request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!dated && !fromValue.isEmpty()) {
            try {
                from = LocalDate.parse(fromValue);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
            }
        }
        if (dated) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            try {
                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
            } catch (DateTimeParseException e) {
                throw new InvalidSheetException((numbering ? "The period numbering from" : "The policy date")
                        + " must be a date (YYYY-MM-DD), or blank");
            }
            return;
        }
        if (gradeTerms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, null, from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (terms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), from, request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
            return;
        }
        if (value.isEmpty() && floor) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), from, request.user()));
            return;
        }
        if (value.isEmpty() && late) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
            return;
        }
        if (value.isEmpty()) {
            body.set(new SettingInput(key, null, from, request.user()));
            return;
        }
        if (!LIMIT.matcher(value).matches()) {
            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
                    : late ? "The late percent must be 0.00 or more with up to two decimals"
                    : proof ? "The proof threshold must be 0.00 or more with up to two decimals, or blank"
                    : note ? "The note threshold must be 0.00 or more with up to two decimals, or blank"
                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
        }
        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
    }

    /** The roles listed, comma separated without spaces, or null when blank (the standing rule). */
    private static String perm(String raw) throws InvalidSheetException {
        String value = raw == null ? "" : raw.trim();
        if (value.isEmpty()) {
            return null;
        }
        List<String> roles = new ArrayList<>();
        for (String part : value.split(",")) {
            String role = part.trim();
            if (Role.of(role) == null || Role.of(role) == Role.VIEWER) {
                throw new InvalidSheetException("A permission lists roles (clerk, steward), comma separated, or is blank");
            }
            if (!roles.contains(role)) {
                roles.add(role);
            }
        }
        return String.join(",", roles);
    }
}
# GET /api/sheets/{sheetId}/settings — the sheet's settings in force on its today: clerk-limit (two
# decimals, null for no limit) and floor (two decimals, 1.00 until set), and so on; and the floor and
# late percent recorded by from-date (floorFrom, latePctFrom).
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ readonly-transaction ]
# POST /api/sheets/{sheetId}/settings — change a setting (body: {key, value, from, user}). The keys are
# clerk-limit: a number of 0.00 or more with up to two decimals, or blank for no limit; and floor: the
# least a claim's live due may be, 0.00 or more with up to two decimals, blank for its default 1.00; and
# terms: the whole days (0 or more) after its date a claim is due by, blank for its default 14; and
# terms-A, terms-B, terms-C: a grade's own terms, which a claim of a person of that grade (on the claim's
# date) takes instead, blank to use the sheet's terms (a claim's due-by is fixed when it is added); and
# late-pct: the percent of an overdue claim's figure charged per full 30 days overdue, 0.00 or more with
# up to two decimals, blank for its default 0.00; and cap: the most a person's due-total may be, 0.00 or
# more with up to two decimals, or blank for none; note-threshold: the due above which a claim needs a
# note before it is opened, 0.00 or more with up to two decimals, or blank for none; and proof-threshold: the due above which a claim needs a
# proof before it is settled or approved, 0.00 or more with up to two decimals, or blank for none.
# Each of these is dated: its value is recorded from the from-date (yyyy-MM-dd, blank for the sheet's
# today), keeping the values recorded from other dates and replacing one recorded from the same date. A
# claim's floor, late percent, terms and proof threshold are those in force on its date; the clerk limit and cap those in
# force on the sheet's today. policy-date and period-numbering-from are not dated (from is ignored).
# Any other key or value is refused (400) and nothing is stored. A stored change is recorded in the
# audit file as SETTING_CHANGED, ending from=<date> when a from-date was given (even when the value is the one already in force), then ROLLUP/TOTALS
# for the figures it moved; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.setting.SaveSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ transaction ]
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Settings, settingsKey, useSettings } from './settings';

const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

/** The standing rule each action keeps while its permission is blank. */
const STANDING_PERMS: Record<(typeof PERM_ACTIONS)[number], string> = {
  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', reassign: 'steward', close: 'clerk,steward', reopen: 'steward',
};

type PermKey = `perm-${(typeof PERM_ACTIONS)[number]}`;

type Key = 'clerk-limit' | 'floor' | 'terms' | 'terms-A' | 'terms-B' | 'terms-C' | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'cap' | 'proof-threshold' | 'note-threshold' | 'grace-days' | PermKey;

const GRADES = ['A', 'B', 'C'] as const;

/** The settings that carry a figure: each is saved from a from-date (blank for the sheet's today). */
type DatedKey = Exclude<Key, 'policy-date' | 'period-numbering-from' | 'grace-days' | PermKey>;

const NO_FROM: Record<DatedKey, string> = { 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'late-pct': '', cap: '', 'proof-threshold': '', 'note-threshold': '' };

const isDated = (k: Key): k is DatedKey => k in NO_FROM;

// The sheet's settings in force, and the form that changes them: the clerk limit (blank for none),
// the floor (blank for its default), the terms in days (blank for 14), each grade's own terms (blank
// for the sheet's terms) and the late percent (blank for
// 0.00), the policy date rounding turns on (blank for the sheet's today) and the date claims opened
// are numbered per period from (blank for off), and the cap on a person's due-total (blank for none), and the proof threshold above which a claim's due needs a proof to be settled or approved (blank for none), and the note threshold above which a claim's due needs a note to be opened (blank for none). Saving changes the setting last touched, so a field left blank does not clear the others.
// Each setting that carries a figure is saved from its from-date (blank for the sheet's today), and shows
// the value in force on the sheet's today; the policy date and period numbering date are not dated.
// The permission matrix gives, for each action, the roles that may take it, comma separated (blank keeps
// the standing rule, shown as the placeholder); it is not dated. The grace days (blank for off, not
// dated) are the whole days after its to-date an open period is closed when the sheet's today moves.
function SheetSettings() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const settings = useSettings(sheet);
  const [values, setValues] = useState<Record<Key, string>>({ 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', cap: '', 'proof-threshold': '', 'note-threshold': '', 'grace-days': '',
    'perm-open': '', 'perm-settle': '', 'perm-void': '', 'perm-reassign': '', 'perm-close': '', 'perm-reopen': '' });
  const [froms, setFroms] = useState<Record<DatedKey, string>>(NO_FROM);
  const [key, setKey] = useState<Key>('clerk-limit');
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: ({ key, value, from }: { key: Key; value: string; from: string }) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { key, value, from, user }),
    onSuccess: async (_, { key }) => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
      setValues((v) => ({ ...v, [key]: '' }));
      if (isDated(key)) setFroms((f) => ({ ...f, [key]: '' }));
    },
  });
  const submit = useSubmitOnce(save);

  const field = (k: Key, placeholder: string, inputMode: 'decimal' | 'text' = 'decimal') => (
    <input
      data-testid={`setting-${k}`}
      placeholder={placeholder}
      inputMode={inputMode}
      value={values[k]}
      onFocus={() => setKey(k)}
      onChange={(e) => {
        setValues({ ...values, [k]: e.target.value });
        setKey(k);
        save.reset();
      }}
    />
  );

  const from = (k: DatedKey) => (
    <input
      data-testid={`setting-${k}-from`}
      placeholder="From YYYY-MM-DD (blank for today)"
      value={froms[k]}
      onFocus={() => setKey(k)}
      onChange={(e) => {
        setFroms({ ...froms, [k]: e.target.value });
        setKey(k);
        save.reset();
      }}
    />
  );

  return (
    <section data-testid="settings">
      <h2>Settings</h2>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ key, value: values[key], from: isDated(key) ? froms[key] : '' });
        }}
      >
        Clerk limit <strong data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</strong>{' '}
        {field('clerk-limit', 'Clerk limit (blank for none)')}{' '}{from('clerk-limit')}{' '}
        Floor <strong data-testid="setting-floor-current">{settings.data?.floor ?? ''}</strong>{' '}
        {field('floor', 'Floor (blank for 1.00)')}{' '}{from('floor')}{' '}
        Terms <strong data-testid="setting-terms-current">{settings.data?.terms ?? ''}</strong>{' '}
        {field('terms', 'Terms in days (blank for 14)')}{' '}{from('terms')}{' '}
        {GRADES.map((g) => (
          <span key={g}>
            Terms {g} <strong data-testid={`setting-terms-${g}-current`}>{settings.data?.gradeTerms?.[g] ?? ''}</strong>{' '}
            {field(`terms-${g}`, `Terms for grade ${g} (blank for the sheet's)`)}{' '}{from(`terms-${g}`)}{' '}
          </span>
        ))}
        Late percent <strong data-testid="setting-late-pct-current">{settings.data?.latePct ?? ''}</strong>{' '}
        {field('late-pct', 'Late percent (blank for 0.00)')}{' '}{from('late-pct')}{' '}
        Policy date <strong data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</strong>{' '}
        {field('policy-date', 'Policy date YYYY-MM-DD (blank for today)', 'text')}{' '}
        Period numbering from <strong data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</strong>{' '}
        {field('period-numbering-from', 'Period numbering from YYYY-MM-DD (blank for off)', 'text')}{' '}
        Cap <strong data-testid="setting-cap-current">{settings.data?.cap ?? ''}</strong>{' '}
        {field('cap', 'Cap (blank for none)')}{' '}{from('cap')}{' '}
        Proof threshold <strong data-testid="setting-proof-threshold-current">{settings.data?.proofThreshold ?? ''}</strong>{' '}
        {field('proof-threshold', 'Proof threshold (blank for none)')}{' '}{from('proof-threshold')}{' '}
        Note threshold <strong data-testid="setting-note-threshold-current">{settings.data?.noteThreshold ?? ''}</strong>{' '}
        {field('note-threshold', 'Note threshold (blank for none)')}{' '}{from('note-threshold')}{' '}
        Grace days <strong data-testid="setting-grace-days-current">{settings.data?.graceDays ?? ''}</strong>{' '}
        {field('grace-days', 'Grace days (blank for off)')}{' '}
        {PERM_ACTIONS.map((a) => (
          <span key={a}>
            May {a} <strong data-testid={`setting-perm-${a}-current`}>{settings.data?.perms?.[a] ?? ''}</strong>{' '}
            {field(`perm-${a}`, `Roles that may ${a}, comma separated (blank for ${STANDING_PERMS[a]})`, 'text')}{' '}
          </span>
        ))}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The settings were refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 48, Component: SheetSettings });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
 *  whole days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
 *  claim's figure charged at each full 30 days it is overdue (the one in force on that boundary); `policyDate` (yyyy-MM-dd) is the date
 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
 *  due-total may be, null for no cap; `proofThreshold` (two decimals) is the due above which a claim needs a proof
 *  before it is settled or approved, null for none; `noteThreshold` (two decimals) is the due above which a
 *  claim needs a note before it is opened, null for none. Each of these that carries a figure is the one in force on the sheet's today.
 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
 *  a claim's floor and late percent are those in force on its date. `perms` is the permission matrix: the roles
 *  that may take each action (open, settle, void, reassign, close, reopen), comma separated, by action; null when
 *  blank (the standing rule). `graceDays` is the whole days after its to-date an open period is closed when the
 *  sheet's today moves, null when blank (off). */
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; proofThreshold: string | null;
  floorFrom: Dated[]; latePctFrom: Dated[]; perms: Record<string, string | null>;
  graceDays: string | null; noteThreshold: string | null };

/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
export type Dated = { from: string; value: string | null };

/** The floor a sheet has before any is recorded. */
const STARTING_FLOOR = '1.00';

/** The late percent a sheet has before any is recorded. */
const STARTING_LATE_PCT = '0.00';

/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
export function valueOn(history: Dated[], date: string, starting: string): string {
  let found: string | null = null;
  for (const d of history) if (d.from <= date) found = d.value;
  return found ?? starting;
}

/** The floor in force on each date; undefined until the settings are read. */
export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
}

/** The late percent in force on each date; undefined until the settings are read. */
export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.latePctFrom, date, STARTING_LATE_PCT));
}

/** Under the sheet's key, so loading the sheet again re-reads its settings. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

export function useSettings(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(settingsKey(sheet), asOf),
    queryFn: () => getJson<Settings>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/settings`, asOf)),
    enabled: sheet !== '',
  });
}
-- The roles the sheet assigns: a user name with no row here is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(32)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's settings, by key; a null value is blank (for clerk-limit: no limit). A key with no
-- row here has never been set.
CREATE TABLE sheet_setting (
    sheet_id    VARCHAR(255) NOT NULL,
    setting_key VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key)
);
-- The settings that carry a figure are dated: each value is recorded from a from-date, and the value in
-- force on a date is the one with the latest from-date on or before it (before every from-date, the
-- sheet's starting value). A null value is blank (for clerk-limit and cap: none; for a grade's terms:
-- the sheet's). The policy date and the period numbering date stay undated in sheet_setting.
CREATE TABLE sheet_setting_from (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(255),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- A value set before settings were dated holds from the start.
INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
    WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');

