# POST /api/sheets/{sheetId}/people/{personId}/watch — toggle whether the user watches the person (body:
# {user}): starts watching when they do not, stops when they do. Refused (400), storing nothing, when no
# user is given or the person is not on the sheet. A stored toggle is recorded in the audit file as
# PERSON_WATCHED or PERSON_UNWATCHED. A watcher is told (NOTIFY) of each claim of the person's settled,
# approved or re-settled.
validate:
  class: net.officefloor.hq.app.watch.ValidateWatch
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: toggle
toggle:
  class: net.officefloor.hq.app.watch.ToggleWatch
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.watch.AuditWatch
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateWatch {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody WatchRequest request, Out<WatchRequest> body,
            SheetStore sheets) throws InvalidSheetException {
        sheets.refuseArchived(sheetId.trim());
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSheetException("Sign in to watch a person");
        }
        body.set(new WatchRequest(request.user().trim()));
    }
}
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : Role.valueOf(found.get(0));
    }

    /** Refuses any change to an archived sheet, and any change by a viewer: a viewer may change nothing
     *  on the sheet. */
    public void refuseChange(String sheetId, String user) throws InvalidSheetException {
        sheets.refuseArchived(sheetId);
        if (find(sheetId, user == null ? "" : user.trim()) == Role.VIEWER) {
            throw new InvalidSheetException("A viewer may change nothing");
        }
    }

    public void set(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }
}

