import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Gives each selected person the grade from the from-date, in list order (the order they were added),
 *  exactly as the person form's edit would (keeping their name and terms), each recorded as PERSON_EDITED
 *  and then how it moved the sheet's figures. A selected person not on the sheet refuses the whole change. */
public class GradePeople {
    public void grade(@PathVariable("sheetId") String sheetId, @Val BulkGradeInput input, PersonStore store,
            SheetStore sheets, RollupService rollups, Audit audit, Out<BulkGradeResult> result)
            throws InvalidSheetException, StalePersonException {
        String sheet = sheetId.trim();
        List<Person> selected = new ArrayList<>();
        for (Long id : input.personIds()) {
            Person person = store.find(sheet, id);
            if (person == null) {
                throw new InvalidSheetException("No such person: " + id);
            }
            selected.add(person);
        }
        selected.sort(Comparator.comparingLong(Person::getId));
        LocalDate today = sheets.today(sheet);
        for (Person person : selected) {
            Rollup before = rollups.snapshot(sheet);
            ApplyPerson.applyGrade(person, input.grade(), input.gradeFrom(), today);
            if (!store.save(person)) {
                throw new StalePersonException();
            }
            audit.record("PERSON_EDITED sheet=" + sheet + " by=" + input.user() + " name=" + person.getName()
                    + " grade=" + person.gradeOn(today));
            rollups.record(sheet, input.user(), before);
        }
        result.set(new BulkGradeResult(selected.size()));
    }
}
# POST /api/sheets/{sheetId}/bulk-grade — give the selected people a grade together (body {personIds,
# grade, gradeFrom, user}). Each selected person, in list order (the order they were added), is given
# the grade from gradeFrom (the sheet's today when blank) exactly as the person form's edit would,
# keeping their name and terms, and recorded as PERSON_EDITED, then how it moved the sheet's figures.
# Answers {graded}. Refused (400), storing nothing, when no person is selected, one is not on the
# sheet, the grade is not A, B or C, gradeFrom is not a date, or the user may change nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateBulkGrade
  next: grade
grade:
  class: net.officefloor.hq.app.person.GradePeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithBulkGrade
  govern: [ transaction ]

